sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float dustAmount;
uniform float dustSize;
uniform float darkSpecks;
uniform float scratchAmount;
uniform float scratchWidth;
layout(color) uniform half4 dustColor;
uniform float fps;
uniform float seed;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float2 hash22(float2 p) {
    return float2(hash21(p), hash21(p + float2(17.31, 5.17)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float t = floor(time * fps) + seed * 3.7;
    float cellS = dustSize * 10.0;
    float2 g = floor(coord / cellS);
    float2 rp = (hash22(g + t) * 0.7 + 0.15) * cellS + g * cellS;
    float live = step(1.0 - dustAmount * 0.35, hash21(g * 1.31 + t * 2.0));
    float rad = dustSize * (0.5 + hash21(g + t + 4.2));
    float dust = (1.0 - smoothstep(rad * 0.6, rad, length(coord - rp))) * live;
    float dark = step(1.0 - darkSpecks, hash21(g * 0.7 + t));
    float scr = 0.0;
    for (int k = 0; k < 4; k++) {
        float fk = float(k);
        float x = hash21(float2(t * 1.7 + fk, 3.1)) * size.x;
        float on = step(1.0 - scratchAmount * 0.6, hash21(float2(t + fk * 5.3, 8.9)));
        float y0 = hash21(float2(t + fk, 2.2)) * size.y;
        float len = (0.2 + 0.6 * hash21(float2(t, fk + 7.7))) * size.y;
        float lineM = 1.0 - smoothstep(0.0, scratchWidth, abs(coord.x - x + sin(coord.y * 0.02 + fk) * 2.0));
        float within = step(y0, coord.y) * step(coord.y, y0 + len);
        scr = max(scr, lineM * on * within);
    }
    float3 o = s;
    o = mix(o, float3(dustColor.rgb), dust * (1.0 - dark));
    o = mix(o, o * 0.1, dust * dark);
    o = mix(o, float3(dustColor.rgb), scr * 0.8);
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), opacity);
}
